`timescale 1ns/1ps
`default_nettype none
// tb_lockin_offsetsim: lock-in amplitude gain vs reference frequency offset.
//
// Sample table (offsim_samples.hex) is pre-generated by gen_offsim.py for one
// specific offset: two-tone 30 MHz+offset, 600/300 counts, pdiff=+90 deg,
// 5 integration windows long (5*65536 clk cycles).  The DUT runs at
// cfg_fcw=FCW(30 MHz), R16, integration_log2=12.  We print every published
// window result; the LAST two windows are the steady-state gain measurement.
//
// After the gain phase we commit +fcw2 (default: FCW of 30.000708 MHz, i.e.
// a fine-tuned reference ABOVE the old config_ok bound) and verify the
// widened config bound accepts it (active_fcw must take the new value).
//
// Phase convention as tb_lockin_ref30m: Q=-x*sin, I=x*cos.
module tb_lockin_offsetsim;
    localparam FCW30  = 32'd1982292598;   // exactly 30 MHz
    localparam NLINES = 5*65536;

    reg clk=0, rst_n=0;
    always #7.69 clk = ~clk;

    reg adc_valid = 1'b1;
    reg signed [11:0] x0=0, x1=0;

    reg [31:0] mem [0:NLINES-1];
    integer idx = 0;
    initial begin
        $readmemh("offsim_samples.hex", mem);
    end
    always @(posedge clk) begin
        if (adc_valid) begin
            x0 <= {{4{mem[idx][11]}},  mem[idx][11:0]};
            x1 <= {{4{mem[idx][27]}},  mem[idx][27:16]};
            idx <= (idx == NLINES-1) ? 32'd0 : idx + 32'd1;
        end
    end

    reg cfg_commit=0, cfg_enable=0;
    reg [31:0] cfg_fcw = FCW30;
    reg [1:0]  cfg_decim_sel = 2'd0;
    reg [4:0]  cfg_integration_log2 = 5'd12;

    wire lockin_valid, result_present, ratio_valid;
    wire [23:0] amp0_q12, amp1_q12;
    wire signed [15:0] phase0_turn, phase1_turn, phase_diff_turn;
    wire [31:0] ratio_q16, flags, gap_count, drop_count, result_id, result_age;
    wire [1:0] detected, qualified;
    wire [31:0] active_fcw;

    lockin_measurement #(
        .CLK_FREQ(32'd65000000),
        .MIN_AMPLITUDE_Q12(24'd2048)
    ) dut (
        .clk(clk), .rst_n(rst_n),
        .adc_valid(adc_valid), .adc_ch0(x0), .adc_ch1(x1),
        .cfg_commit(cfg_commit),.cfg_reconfig(1'b0), .cfg_enable(cfg_enable),
        .cfg_fcw(cfg_fcw), .cfg_decim_sel(cfg_decim_sel),
        .cfg_integration_log2(cfg_integration_log2),
        .disp_fcw(cfg_fcw), .disp_decim(cfg_decim_sel),
        .disp_integration(cfg_integration_log2),
        .lockin_valid(lockin_valid),
        .amp0_q12(amp0_q12), .amp1_q12(amp1_q12),
        .phase0_turn(phase0_turn), .phase1_turn(phase1_turn),
        .phase_diff_turn(phase_diff_turn),
        .ratio_q16(ratio_q16),
        .flags(flags), .gap_count(gap_count), .drop_count(drop_count),
        .result_present(result_present), .ratio_valid(ratio_valid),
        .result_id(result_id), .result_age(result_age),
        .detected(detected), .qualified(qualified),
        .active_fcw(active_fcw)
    );

    integer wins = 0;
    reg [23:0] last_amp0, last_amp1;
    reg signed [15:0] last_pdiff;
    reg [1:0] last_det, last_qual;
    always @(posedge clk) begin
        if (lockin_valid) begin
            wins = wins + 1;
            last_amp0 = amp0_q12;  last_amp1 = amp1_q12;
            last_pdiff = phase_diff_turn;
            last_det = detected;   last_qual = qualified;
            $display("WIN%0d amp0=%0d amp1=%0d pdiff=%0d det=%b qual=%b",
                     wins, amp0_q12, amp1_q12, $signed(phase_diff_turn),
                     detected, qualified);
        end
    end

    // plusargs
    reg [1023:0] fcw2_str;
    integer fcw2 = 1982339446;   // FCW(30.000708 MHz) default

    initial begin
        if (!$value$plusargs("fcw2=%d", fcw2))
            fcw2 = 1982339446;
        #100;
        rst_n = 1;
        @(posedge clk);
        cfg_enable = 1'b1;
        cfg_commit = 1'b1;
        @(posedge clk);
        cfg_commit = 1'b0;

        // stream all 5 windows
        #(NLINES * 15.4 * 2);

        $display("OFFSIM amp0=%0d amp1=%0d pdiff=%0d det=%b qual=%b wins=%0d",
                 last_amp0, last_amp1, $signed(last_pdiff), last_det, last_qual, wins);

        // fine-tuned reference acceptance (config bound widened to Nyquist)
        @(posedge clk);
        cfg_fcw <= fcw2;
        cfg_commit <= 1'b1;
        @(posedge clk);
        cfg_commit <= 1'b0;
        #(65536 * 15.4 * 2);
        if (active_fcw !== fcw2[31:0]) begin
            $display("TB_ERROR: active_fcw=%0d did not take tuned fcw2=%0d", active_fcw, fcw2);
            $display("TB_FAIL tb_lockin_offsetsim");
        end else begin
            $display("TUNED_ACCEPT active_fcw=%0d", active_fcw);
            // steady-state amplitude with the fine-tuned reference (last window)
            $display("TUNED_AMP amp0=%0d amp1=%0d pdiff=%0d", last_amp0, last_amp1, $signed(last_pdiff));
            $display("TB_PASS tb_lockin_offsetsim");
        end
        $finish;
    end
endmodule
`default_nettype wire
